# Step 6:  Define a function to evaluate the given formula
def evaluate_formula(formula, P, Q, R):
    if formula == "0":
        return 0
    elif formula == "1":
        return 1
    elif formula == "2":
        return 2
    elif formula == "P":
        return P
    elif formula == "Q":
        return Q
    elif formula == "R":
        return R
    elif formula.startswith("-"):
        return 2 - evaluate_formula(formula[1:], P, Q, R)
    elif formula.startswith("("):
        count = 0
        op_index = -1
        for i in range(len(formula)):
            if formula[i] == "(":
                count += 1
            elif formula[i] == ")":
                count -= 1
            elif formula[i] in "*+" and count == 1:
                op_index = i
                break
        # Step 7:  Evaluate the subformulas

        left = evaluate_formula(formula[1:op_index], P, Q, R)
        right = evaluate_formula(formula[op_index+1:-1], P, Q, R)
        if formula[op_index] == "*":
            return min(left, right)
        else:
            return max(left, right)

# Step 8:  Read input
input_formulas = []
while True:
    formula = input()
    if formula == ".":
        break
    input_formulas.append(formula)

# Step 9:  For each formula, evaluate the formula for all possible combinations of P, Q, and R
for formula in input_formulas:
    count = 0
    for P in range(3):
        for Q in range(3):
            for R in range(3):
                if evaluate_formula(formula, P, Q, R) == 2:
                    count += 1
    print(count)

```

