Here's a Java program that prints out the contents of a given two-dimensional array in a spiral pattern:

```java
public class SpiralPrint {
    public static void spiralPrint(int[][] arr) {
        int topRow = 0;
        int bottomRow = arr.length - 1;
        int leftColumn = 0;
        int rightColumn = arr[0].length - 1;
        int direction = 0;

        while (topRow <= bottomRow && leftColumn <= rightColumn) {
            if (direction == 0) {
                for (int i = leftColumn; i <= rightColumn; i++) {
                    System.out.print(arr[topRow][i] + " ");
                }
                topRow++;
            } else if (direction == 1) {
                for (int i = topRow; i <= bottomRow; i++) {
                    System.out.print(arr[i][rightColumn] + " ");
                }
                rightColumn--;
            } else if (direction == 2) {
                for (int i = rightColumn; i >= leftColumn; i--) {
                    System.out.print(arr[bottomRow][i] + " ");
                }
                bottomRow--;
            } else if (direction == 3) {
                for (int i = bottomRow; i >= topRow; i--) {
                    System.out.print(arr[i][leftColumn] + " ");
                }
                leftColumn++;
            }

            direction = (direction + 1) % 4;
        }
    }

    public static void main(String[] args) {
        int[][] arr = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
        spiralPrint(arr);
    }
}
